110:     Data data = new Data(ImmutableMap.copyOf(strings), ImmutableMap.copyOf(objects));
111:     ByteBuf buffer = bufferAllocator.buffer();
112:     OutputStream outputStream = new ByteBufOutputStream(buffer);
113:     try {
114:       defaultSerializer.serialize(Data.class, data, outputStream);
115:       outputStream.close();
116:       return buffer;
117:     } catch (Throwable e) {
118:       buffer.release();
119:       throw Exceptions.uncheck(e);
120:     }
121:   }
