131:   @Override
132:   public Operation terminate() {
133:     return storeAdapter.remove(sessionId)
134:       .next(() -> {
135:         sessionId.terminate();
136:         hydrate(Unpooled.buffer(0, 0));
137:       });
138:   }
139: 
140:   private void markDirty() {
141:     status.setDirty(true);
142:   }
143: 
144:   private class Sync implements SyncSession {
145: 
146:     @Override
147:     public Optional<String> get(String key) {
