153:       return get(key, defaultSerializer);
154:     }
155: 
156:     @Override
157:     public <T> Optional<? extends T> get(Class<T> key, SessionValueSerializer serializer) {
158:       byte[] bytes = objects.get(key);
159:       if (bytes == null) {
160:         return Optional.empty();
161:       } else {
162:         try {
163:           return Optional.of(serializer.deserialize(key, new ByteArrayInputStream(bytes)));
164:         } catch (IOException e) {
165:           throw Exceptions.uncheck(e);
166:         }
167:       }
168:     }
