88:   private void hydrate(ByteBuf data) {
89:     if (data.readableBytes() > 0) {
90:       try {
91:         Data deserializedData = defaultSerializer.deserialize(Data.class, new ByteBufInputStream(data));
92:         this.strings.clear();
93:         this.strings.putAll(deserializedData.strings);
94:         this.objects.clear();
95:         this.objects.putAll(deserializedData.objects);
96:         sessionStatus.setDirty(false);
