359:   public void lastModified(Date date, Runnable runnable) {
360:     Date ifModifiedSinceHeader = requestConstants.request.getHeaders().getDate(IF_MODIFIED_SINCE);
361:     long lastModifiedSecs = date.getTime() / 1000;
362: 
363:     if (ifModifiedSinceHeader != null) {
364:       long time = ifModifiedSinceHeader.getTime();
365:       long ifModifiedSinceSecs = time / 1000;
366: 
367:       if (lastModifiedSecs == ifModifiedSinceSecs) {
368:         requestConstants.response.status(NOT_MODIFIED.code()).send();
369:         return;
370:       }
371:     }
372: 
373:     requestConstants.response.getHeaders().setDate(HttpHeaderConstants.LAST_MODIFIED, date);
374:     runnable.run();
375:   }
