32:   public static PathBinder parse(String path, boolean exact) {
33:     PathBinderBuilder pathBinderBuilder = new DefaultPathBinderBuilder();
34: 
35:     Matcher matchResult = PLACEHOLDER.matcher(path);
36: 
37:     int lastIndex = 0;
38: 
39:     if (matchResult.find()) {
40:       do {
41:         int thisIndex = matchResult.start();
42:         if (thisIndex != lastIndex) {
43:           pathBinderBuilder.literal(path.substring(lastIndex, thisIndex));
44:         }
45:         lastIndex = matchResult.end();
46:         String component = matchResult.group(0);
47:         boolean found = false;
48:         for (TokenType type : TokenType.values()) {
49:           if (type.match(component, pathBinderBuilder)) {
50:             found = true;
