24: import java.time.Clock;
25: import java.time.Duration;
26: import java.time.Instant;
27: import java.util.Queue;
28: import java.util.concurrent.atomic.AtomicBoolean;
29: import java.util.concurrent.atomic.AtomicReference;
30: 
31: public class CachingUpstream<T> implements Upstream<T> {
32: 
33:   private Upstream<? extends T> upstream;
34: 
35:   private final Clock clock;
36:   private final AtomicReference<Cached<? extends T>> ref = new AtomicReference<>();
37:   private final Function<? super ExecResult<T>, Duration> ttlFunc;
38: 
39:   private final AtomicBoolean pending = new AtomicBoolean();
40:   private final AtomicBoolean draining = new AtomicBoolean();
41:   private final Queue<Downstream<? super T>> waiting = PlatformDependent.newMpscQueue();
42: 
43:   public CachingUpstream(Upstream<? extends T> upstream, Function<? super ExecResult<T>, Duration> ttl) {
44:     this(upstream, ttl, Clock.systemUTC());
45:   }
46: 
47:   @VisibleForTesting
48:   CachingUpstream(Upstream<? extends T> upstream, Function<? super ExecResult<T>, Duration> ttl, Clock clock) {
49:     this.upstream = upstream;
50:     this.ttlFunc = ttl;
51:     this.clock = clock;
52:   }
53: 
54:   private void tryDrain() {
55:     if (draining.compareAndSet(false, true)) {
56:       try {
57:         Cached<? extends T> loading = ref.get();
58:         if (needsFetch(loading)) {
59:           if (pending.compareAndSet(false, true)) {
60:             Downstream<? super T> downstream = waiting.poll();
61:             if (downstream == null) {
62:               pending.set(false);
63:             } else {
64:               try {
65:                 yield(downstream);
66:               } catch (Throwable e) {
67:                 receiveResult(downstream, ExecResult.of(Result.error(e)));
68:               }
69:             }
70:           }
71:         } else {
72:           Downstream<? super T> downstream = waiting.poll();
73:           while (downstream != null) {
74:             downstream.accept(loading.result);
75:             downstream = waiting.poll();
76:           }
77:         }
78:       } finally {
79:         draining.set(false);
80:       }
81:     }
82: 
83:     if (!waiting.isEmpty() && !pending.get() && needsFetch(ref.get())) {
84:       tryDrain();
85:     }
86:   }
87: 
88:   private boolean needsFetch(Cached<? extends T> cached) {
89:     return cached == null || (cached.expireAt != null && cached.expireAt.isBefore(clock.instant()));
90:   }
91: 
92:   private void yield(final Downstream<? super T> downstream) throws Exception {
93:     upstream.connect(new Downstream<T>() {
94:       public void error(Throwable throwable) {
95:         receiveResult(downstream, ExecResult.of(Result.<T>error(throwable)));
96:       }
97: 
98:       @Override
99:       public void success(T value) {
100:         receiveResult(downstream, ExecResult.of(Result.success(value)));
101:       }
102: 
103:       @Override
104:       public void complete() {
105:         receiveResult(downstream, CompleteExecResult.get());
106:       }
107:     });
108:   }
109: 
110:   @Override
111:   public void connect(Downstream<? super T> downstream) throws Exception {
112:     Cached<? extends T> cached = this.ref.get();
113:     if (needsFetch(cached)) {
114:       Promise.<T>async(d -> {
115:         waiting.add(d);
116:         tryDrain();
117:       }).result(downstream::accept);
118:     } else {
119:       downstream.accept(cached.result);
120:     }
121:   }
