25: public class LazyChildRegistry extends HierarchicalRegistrySupport {
26: 
27:   private final Class<?> type;
28:   private final Factory<?> factory;
29:   private Object object;
30:   private Lock lock = new ReentrantLock();
31: 
32:   public <T> LazyChildRegistry(Registry parent, Class<T> type, Factory<? extends T> factory) {
33:     super(parent);
34:     this.type = type;
35:     this.factory = factory;
36:   }
37: 
38:   @Override
39:   protected <T> T doMaybeGet(Class<T> requestedType) {
40:     if (type.isAssignableFrom(requestedType)) {
41:       return requestedType.cast(getObject());
42:     } else {
43:       return null;
44:     }
45:   }
46: 
47:   private Object getObject() {
48:     if (object == null) {
49:       lock.lock();
50:       try {
51:         //noinspection ConstantConditions
52:         if (object == null) {
53:           object = factory.create();
54:         }
55:       } finally {
56:         lock.unlock();
57:       }
58:     }
59:     return object;
60:   }
61: 
62:   @Override
63:   protected String describe() {
64:     return "LazyHierarchicalRegistry{" + type.getName() + "}";
65:   }
