17: package ratpack.groovy.internal.capture;
18: 
19: import groovy.lang.Closure;
20: import org.codehaus.groovy.runtime.ComposedClosure;
21: import ratpack.func.Block;
22: import ratpack.func.Function;
23: import ratpack.groovy.Groovy;
24: import ratpack.groovy.internal.ClosureUtil;
25: import ratpack.util.Exceptions;
26: import ratpack.util.internal.Paths2;
27: 
28: import java.nio.charset.StandardCharsets;
29: import java.nio.file.Path;
30: 
31: public class RatpackDslClosures {
32: 
33:   private Closure<?> handlers;
34:   private Closure<?> bindings;
35:   private Closure<?> serverConfig;
36:   private Path thisScript;
37:   private boolean closed;
38: 
39:   public RatpackDslClosures(Path rootScript) {
40:     this.handlers = Closure.IDENTITY;
41:     this.bindings = Closure.IDENTITY;
42:     this.serverConfig = Closure.IDENTITY;
43:     this.thisScript = rootScript;
44:   }
45: 
46:   public Closure<?> getHandlers() {
47:     return handlers;
48:   }
49: 
50:   public Closure<?> getBindings() {
51:     return bindings;
52:   }
53: 
54:   public Closure<?> getServerConfig() {
55:     return serverConfig;
56:   }
57: 
58:   public void setHandlers(Closure<?> handlers) {
59:     assertAtTopLevelOfRatpackDsl("handlers");
60:     this.handlers = new ComposedClosure<>(this.handlers, handlers);
61:   }
62: 
63:   public void setBindings(Closure<?> bindings) {
64:     assertAtTopLevelOfRatpackDsl("bindings");
65:     this.bindings = new ComposedClosure<>(this.bindings, bindings);
66:   }
67: 
68:   public void setServerConfig(Closure<?> serverConfig) {
69:     assertAtTopLevelOfRatpackDsl("serverConfig");
70:     this.serverConfig = new ComposedClosure<>(this.serverConfig, serverConfig);
71:   }
72: 
73:   public void include(Path path) {
74:     assertAtTopLevelOfRatpackDsl("include");
75:     Exceptions.uncheck(() -> {
76:       Path resolvedPath = path;
77:       if (thisScript != null && !path.isAbsolute()) {
78:         resolvedPath = thisScript.resolveSibling(path);
79:       }
80:       String script = Paths2.readText(resolvedPath, StandardCharsets.UTF_8);
81:       RatpackDslClosures closures = new RatpackDslScriptCapture(false, new String[]{}, RatpackDslBacking::new).apply(resolvedPath, script);
82:       this.setServerConfig(closures.getServerConfig());
83:       this.setBindings(closures.getBindings());
84:       this.setHandlers(closures.getHandlers());
85:     });
86:   }
87: 
88:   private void assertAtTopLevelOfRatpackDsl(String methodName) {
89:     if (closed) {
90:       throw new IllegalStateException(methodName + " {} DSL method can only be used at the top level of the ratpack {} block");
91:     }
92:   }
93: 
94:   public static RatpackDslClosures capture(Function<? super RatpackDslClosures, ? extends Groovy.Ratpack> function, Path script, Block action) throws Exception {
95:     RatpackDslClosures closures = new RatpackDslClosures(script);
96:     Groovy.Ratpack receiver = function.apply(closures);
97:     RatpackScriptBacking.withBacking(closure -> ClosureUtil.configureDelegateFirst(receiver, closure), action);
98:     closures.closed = true;
99:     return closures;
100:   }
101: 
102: }
