66:       throw new IllegalArgumentException("uri " + uri + " must be a http or https uri");
67:     }
68: 
69:     host(uri.getHost());
70:     port(uri.getPort());
71:     String rawPath = uri.getRawPath();
72:     if (rawPath != null && !rawPath.isEmpty() && !rawPath.equals("/")) {
