61:   @Override
62:   public void handle(final Context context) throws Exception {
63:     U userProfile = getUserProfile(context);
64:     if (authorizer.isAuthenticationRequired(context) && userProfile == null) {
65:       initiateAuthentication(context);
66:     } else {
67:       if (userProfile != null) {
68:         context.getRequest().register(userProfile);
69:         context.getRequest().register(UserProfile.class, userProfile);
70:         authorizer.handleAuthorization(context, userProfile);
71:       } else {
72:         context.next();
73:       }
74:     }
