87:       ((BaseClient) client).setCallbackUrl(callbackUrl);
88:     }
89:     final RatpackWebContext webContext = new RatpackWebContext(context);
90:     context.blocking(new Callable<Void>() {
91:       @Override
92:       public Void call() throws Exception {
93:         client.redirect(webContext, false, false);
94:         return null;
95:       }
96:     }).onError(new Action<Throwable>() {
97:       @Override
98:       public void execute(Throwable ex) throws Exception {
99:         if (ex instanceof RequiresHttpAction) {
100:           webContext.sendResponse((RequiresHttpAction) ex);
101:         } else {
