57:   private final LoadingCache<TypeToken<?>, List<? extends Supplier<?>>> supplierCache = CacheBuilder.newBuilder().build(new CacheLoader<TypeToken<?>, List<? extends Supplier<?>>>() {
58:     @Override
59:     public List<? extends Supplier<?>> load(@SuppressWarnings("NullableProblems") TypeToken<?> key) throws Exception {
60:       return Objects.firstNonNull(suppliersForTypeFunction.apply(key), ImmutableList.<Supplier<?>>of());
61:     }
62:   });
