70:     private <T> List<? extends Supplier<?>> get(final PredicateCacheability.CacheKey<T> key) throws ExecutionException {
71:       List<? extends Supplier<?>> suppliers = getSuppliers(key.type);
72:       if (suppliers == null || suppliers.isEmpty()) {
73:         return ImmutableList.of();
74:       } else {
75:         return FluentIterable.from(suppliers).filter(new Predicate<Supplier<?>>() {
76:           @Override
77:           public boolean apply(Supplier<?> input) {
78:             @SuppressWarnings("unchecked") T instance = (T) input.get();
79:             return key.predicate.apply(instance);
80:           }
81:         }).toList();
82:       }
83:     }
84:   });
