349:    *               throw new RuntimeException("some other error!");
350:    *             }
351:    *           })
352:    *           .onError(IllegalArgumentException.class, e -> ctx.render("the value is invalid"))
353:    *           .onError(e -> ctx.render("unknown error: " + e.getMessage()))
354:    *           .then(t -> ctx.render("ok"))
