597:    * This method can be used when a subsequent operation on a promise isn't dependent on the actual promised value.
598:    * <p>
599:    * If the upstream promise fails, its error will propagate downstream and the given promise will never be subscribed to.
600:    *
601:    *  <pre class="java">{@code
602:    * import ratpack.test.exec.ExecHarness;
603:    * import ratpack.exec.ExecResult;
604:    * import ratpack.exec.Promise;
605:    *
606:    * import static org.junit.Assert.assertEquals;
607:    *
608:    * public class Example {
609:    *   private static String value;
610:    *
611:    *   public static void main(String... args) throws Exception {
612:    *     ExecResult<String> result = ExecHarness.yieldSingle(c ->
613:    *         Promise.value("foo")
614:    *           .next(v -> value = v)
615:    *           .replace(Promise.value("bar"))
616:    *     );
617:    *
618:    *     assertEquals("bar", result.getValue());
619:    *     assertEquals("foo", value);
620:    *   }
621:    * }
622:    * }</pre>
623:    *
624:    * @param next the promise to replace {@code this} with
625:    * @param <O> the type of the value of the replacement promise
626:    * @return a promise
627:    * @since 1.1
628:    */
629:   default <O> Promise<O> replace(Promise<O> next) {
630:     return flatMap(in -> next);
631:   }
632: 
633:   default <O> Promise<Pair<O, T>> left(Promise<O> left) {
634:     return flatMap(right -> left.map(value -> Pair.of(value, right)));
635:   }
636: 
637:   default <O> Promise<Pair<T, O>> right(Promise<O> right) {
638:     return flatMap(left -> right.map(value -> Pair.of(left, value)));
639:   }
