141:     this(DEFAULT_NAME_TOKEN, DEFAULT_CONCURRENCY_LEVEL);
142:   }
143: 
144:   /**
145:    * Uses the {@link #DEFAULT_CONCURRENCY_LEVEL} and the given name for the health check identifying path token.
