181:    * @param throttle the level of concurrency to use when executing health checks
182:    */
183:   protected HealthCheckHandler(String pathTokenName, int throttle) {
184:     this.name = pathTokenName;
185:     this.throttle = throttle;
186:   }
187: 
188:   /**
189:    * The level of concurrency to use when executing health checks.
190:    *
191:    * @return the level of concurrency to use when executing health checks
