39: public class DefaultExecController implements ExecController {
40: 
41:   private static final ThreadLocal<ExecController> THREAD_BINDING = new ThreadLocal<>();
42: 
43:   private final ThreadLocal<Execution> executionHolder = new ThreadLocal<>();
44: 
45:   private final ListeningScheduledExecutorService computeExecutor;
46:   private final ListeningExecutorService blockingExecutor;
47:   private final EventLoopGroup eventLoopGroup;
48:   private final ExecControl control;
