178:     public static Action<? super RatpackServerSpec> app(boolean compileStatic, String... scriptPaths) {
179:       return b -> {
180:         ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
181: 
182:         BaseDirFinder.Result baseDirResult = Arrays.stream(scriptPaths)
183:           .map(scriptPath -> BaseDirFinder.find(classLoader, scriptPath))
184:           .filter(Optional::isPresent)
185:           .map(Optional::get)
186:           .findFirst()
187:           .orElseThrow(() -> new ScriptNotFoundException(scriptPaths));
188: 
189:         Path baseDir = baseDirResult.getBaseDir();
190:         Path scriptFile = baseDirResult.getResource();
191:         doApp(b, compileStatic, baseDir, scriptFile);
192:       };
193:     }
