195:     private static void doApp(RatpackServerSpec definition, boolean compileStatic, Path baseDir, Path scriptFile) throws Exception {
196:       String script = IoUtils.read(UnpooledByteBufAllocator.DEFAULT, scriptFile).toString(CharsetUtil.UTF_8);
197: 
198:       RatpackDslClosures closures = new RatpackDslScriptCapture(compileStatic, RatpackDslBacking::new).apply(scriptFile, script);
199:       definition.serverConfig(ClosureUtil.configureDelegateFirstAndReturn(loadPropsIfPresent(ServerConfig.builder().baseDir(baseDir), baseDir), closures.getServerConfig()));
200: 
201:       definition.registry(r -> {
202:         return Guice.registry(bindingsSpec -> {
203:           bindingsSpec.bindInstance(new FileBackedReloadInformant(scriptFile));
204:           ClosureUtil.configureDelegateFirst(bindingsSpec, closures.getBindings());
205:         }).apply(r);
206:       });
207: 
208:       definition.handler(r -> {
209:         return Groovy.chain(r, closures.getHandlers());
210:       });
211:     }
