213:     private static ServerConfigBuilder loadPropsIfPresent(ServerConfigBuilder serverConfigBuilder, Path baseDir) {
214:       Path propsFile = baseDir.resolve(BaseDir.DEFAULT_BASE_DIR_MARKER_FILE_PATH);
215:       if (Files.exists(propsFile)) {
216:         serverConfigBuilder.props(propsFile);
217:       }
218:       return serverConfigBuilder;
