37:    */
38:   public MediaType(String headerValue, String defaultCharset) {
39:     // TODO: separate this out into a parser and interface.
40:     if (headerValue == null) {
41:       value = null;
42:       params = Collections.emptyMap();
43:     } else {
44:       headerValue = headerValue.trim();
45:       if (headerValue.length() == 0) {
46:         value = null;
47:         params = Collections.emptyMap();
48:       } else {
49:         params = new LinkedHashMap<String, String>();
50:         String[] parts = headerValue.split(";");
51:         value = parts[0].toLowerCase();
52:         if (parts.length > 1) {
53:           for (int i = 1; i < parts.length; ++i) {
54:             String part = parts[i].trim();
55:             if (part.contains("=")) {
56:               String[] keyValue = part.split("=", 2);
57:               params.put(keyValue[0].toLowerCase(), keyValue[1]);
58:             } else {
59:               params.put(part.toLowerCase(), null);
