95:   }
96: 
97:   public String getCharset() {
98:     return params.get("charset");
99:   }
100: 
101:   public boolean isText() {
102:     return !isEmpty() && getValue().startsWith("text/");
103:   }
104: 
105:   /**
106:    * Is the base {@value #APPLICATION_JSON}?
107:    */
108:   public boolean isJson() {
109:     return !isEmpty() && getValue().equals(APPLICATION_JSON);
110:   }
111: 
112:   /**
113:    * Is the base {@value #APPLICATION_FORM}?
114:    */
115:   public boolean isForm() {
