256:     @Override
257:     public HandlerDecorator get() {
258:       return HandlerDecorator.prepend(new CookieBasedSessionStorageBindingHandler(sessionService,
259:         config.getSessionCookieName(),
260:         config.getPath(),
261:         config.getDomain(),
262:         config.getMaxCookieSize(),
263:         config.getMaxInactivityInterval()));
264:     }
265:   }
