318:    * @param action The action that defines the all chain
319:    * @return A all representing the chain
320:    * @throws Exception any thrown by {@code action}
321:    */
322:   default Handler chain(Action<? super Chain> action) throws Exception {
323:     return Handlers.chain(getServerConfig(), getRegistry(), action);
324:   }
