462:   /**
463:    * Adds a handler that delegates to the given handler if the relative {@code path}
464:    * matches the given {@code path} exactly.
465:    * <p>
466:    * Nesting {@code path} handlers will not work due to the exact matching, use a combination of {@code path}
467:    * and {@code prefix} instead.  See {@link Chain#prefix(String, ratpack.func.Action)} for details.
468:    * <pre>
469:    *   // this will not work
470:    *   path("person/:id") {
471:    *     path("child/:childId") {
472:    *       // a request of /person/2/child/1 will not get passed the first all as it will try
473:    *       // to match "person/2/child/1" with "person/2" which does not match
474:    *     }
475:    *
476:    *   // this will work
477:    *   prefix("person/:id") {
478:    *     path("child/:childId") {
479:    *       // a request of /person/2/child/1 will work this time
480:    *     }
481:    *   }
482:    * </pre>
483:    * <p>
484:    * See {@link Handlers#path(String, Handler)} for the details on how {@code path} is interpreted.
485:    *
486:    * @param path the relative path to match exactly on
487:    * @param handler the handler to delegate to
488:    * @return this
489:    * @see Chain#post(String, Handler)
490:    * @see Chain#get(String, Handler)
491:    * @see Chain#put(String, Handler)
492:    * @see Chain#patch(String, Handler)
493:    * @see Chain#delete(String, Handler)
494:    */
495:   default Chain path(String path, Handler handler) {
496:     return all(Handlers.path(path, handler));
497:   }
