75:  *   protected void configure() {
76:  *     bind(SomeService.class);
77:  *   }
78:  * }
79:  *
80:  * // An action that registers the module with the registry, making it part of the application
81:  * class Bindings implements Action&lt;BindingsSpec&gt; {
82:  *   public void execute(BindingsSpec bindings) {
83:  *     bindings.add(new ServiceModule());
84:  *   }
85:  * }
