88:  * {@literal @}Singleton
89:  * class InjectedHandler implements Handler {
90:  *   private final SomeService service;
91:  *
92:  *   {@literal @}Inject
93:  *   public InjectedHandler(SomeService service) {
94:  *     this.service = service;
95:  *   }
96:  *
97:  *   public void handle(Context exchange) {
98:  *     // …
99:  *   }
100:  * }
