219:    */
220:   public static Handler chain(LaunchConfig launchConfig, Injector parentInjector, Action<? super BindingsSpec> moduleConfigurer, final Action<? super Chain> chainConfigurer) throws Exception {
221:     return new DefaultGuiceBackedHandlerFactory(launchConfig).create(moduleConfigurer, childInjectorFactory(parentInjector), new InjectorHandlerTransformer(launchConfig, chainConfigurer));
222:   }
223: 
224:   /**
225:    * Creates a handler that can be used as the entry point for a Guice backed Ratpack app.
226:    * <p>
227:    * This is a lower level version of {@link #chain(ratpack.launch.LaunchConfig, com.google.inject.Injector, ratpack.func.Action, ratpack.func.Action)}
228:    * that supports a custom final {@link Handler} creation strategy.
229:    *
230:    * @param launchConfig The launch config of the server
231:    * @param parentInjector The injector to use as a parent of the injector to be created
232:    * @param moduleConfigurer The configurer of the {@link BindingsSpec} to back the created handler
233:    * @param injectorTransformer Takes the final {@link Injector} instance that was created from the modules and returns the {@link Handler} to use
234:    * @return A handler that makes all Guice bound objects available to the handlers added to the {@link Chain} given to {@code chainConfigurer}.
235:    */
236:   public static Handler chain(LaunchConfig launchConfig, Injector parentInjector, Action<? super BindingsSpec> moduleConfigurer, Function<? super Injector, ? extends Handler> injectorTransformer) throws Exception {
237:     return new DefaultGuiceBackedHandlerFactory(launchConfig).create(moduleConfigurer, childInjectorFactory(parentInjector), injectorTransformer);
238:   }
239: 
240:   /**
