277:   public static Function<Module, Injector> newInjectorFactory(final LaunchConfig launchConfig) {
278:     final Stage stage = launchConfig.isDevelopment() ? Stage.DEVELOPMENT : Stage.PRODUCTION;
279:     return new Function<Module, Injector>() {
280:       @Override
281:       public Injector apply(Module from) {
282:         return from == null ? createInjector(stage) : createInjector(stage, from);
283:       }
284:     };
285:   }
286: 
287:   /**
288:    * Creates a transformer that can build an injector from a module, as a child of the given parent.
289:    * <p>
290:    * The module given to the {@code transform()} method may be {@code null}.
291:    *
292:    * @param parent The parent injector
293:    * @return a transformer that can build an injector from a module, as a child of the given parent.
294:    */
295:   public static Function<Module, Injector> childInjectorFactory(final Injector parent) {
296:     return new Function<Module, Injector>() {
297:       @Override
298:       public Injector apply(Module from) {
299:         return from == null ? parent.createChildInjector() : parent.createChildInjector(from);
300:       }
301:     };
302:   }
303: 
304:   private static class InjectorHandlerTransformer implements Function<Injector, Handler> {
305:     private final LaunchConfig launchConfig;
306:     private final Action<? super Chain> action;
307: 
308:     public InjectorHandlerTransformer(LaunchConfig launchConfig, Action<? super Chain> action) {
309:       this.launchConfig = launchConfig;
310:       this.action = action;
311:     }
312: 
313:     public Handler apply(Injector injector) throws Exception {
314:       return Handlers.chain(launchConfig, justInTimeRegistry(injector), action);
315:     }
316:   }
317: 
318:   private static class InjectorRegistryBacking implements RegistryBacking {
319:     private final Injector injector;
320: 
321:     public InjectorRegistryBacking(Injector injector) {
322:       this.injector = injector;
323:     }
324: 
325:     @Override
326:     public <T> Iterable<Supplier<? extends T>> provide(TypeToken<T> type) {
327:       return FluentIterable.from(GuiceUtil.allProvidersOfType(injector, type)).transform(new com.google.common.base.Function<Provider<? extends T>, Supplier<? extends T>>() {
328:         @Override
329:         public Supplier<? extends T> apply(final Provider<? extends T> provider) {
330:           return new Supplier<T>() {
331:             @Override
332:             public T get() {
333:               return provider.get();
334:             }
335:           };
336:         }
337:       });
338:     }
339: 
340:     @Override
341:     public boolean equals(Object o) {
342:       if (this == o) {
343:         return true;
344:       }
345:       if (o == null || getClass() != o.getClass()) {
346:         return false;
347:       }
348: 
349:       InjectorRegistryBacking that = (InjectorRegistryBacking) o;
350: 
351:       return injector.equals(that.injector);
352:     }
353: 
354:     @Override
355:     public int hashCode() {
356:       return injector.hashCode();
357:     }
358:   }
359: }
