19: import ratpack.exec.Fulfiller;
20: import ratpack.exec.OverlappingExecutionException;
21: import ratpack.exec.SuccessPromise;
22: import ratpack.exec.internal.DefaultExecController.Execution;
23: import ratpack.func.Action;
24: import ratpack.util.ExceptionUtils;
25: import ratpack.util.internal.InternalRatpackError;
26: 
27: import java.util.concurrent.atomic.AtomicBoolean;
28: 
29: public class DefaultSuccessPromise<T> implements SuccessPromise<T> {
30: 
31:   private final Execution executionFactory;
32:   private final Action<? super Fulfiller<T>> action;
33:   private final Action<? super Throwable> errorHandler;
34: 
35:   public DefaultSuccessPromise(Execution execution, Action<? super Fulfiller<T>> action, Action<? super Throwable> errorHandler) {
36:     this.executionFactory = execution;
37:     this.action = action;
38:     this.errorHandler = errorHandler;
39:   }
40: 
41:   @Override
42:   public void then(final Action<? super T> then) {
43:     try {
44:       executionFactory.continueVia(new Runnable() {
45: 
46:         private final AtomicBoolean fulfilled = new AtomicBoolean();
47: 
48:         @Override
49:         public void run() {
50:           try {
51:             action.execute(new Fulfiller<T>() {
52:               @Override
53:               public void error(final Throwable throwable) {
54:                 if (!fulfilled.compareAndSet(false, true)) {
55:                   new OverlappingExecutionException("promise already fulfilled").printStackTrace();
56:                   return;
57:                 }
58: 
59:                 executionFactory.join(new Action<ratpack.exec.Execution>() {
60:                   @Override
61:                   public void execute(ratpack.exec.Execution execution) throws Exception {
62:                     errorHandler.execute(throwable);
63:                   }
64:                 });
65:               }
66: 
67:               @Override
68:               public void success(final T value) {
69:                 if (!fulfilled.compareAndSet(false, true)) {
70:                   new OverlappingExecutionException("promise already fulfilled").printStackTrace();
71:                   return;
72:                 }
73: 
74:                 executionFactory.join(new Action<ratpack.exec.Execution>() {
75:                   @Override
76:                   public void execute(ratpack.exec.Execution execution) throws Exception {
77:                     then.execute(value);
78:                   }
79:                 });
80:               }
81:             });
82:           } catch (final Exception e) {
83:             if (!fulfilled.compareAndSet(false, true)) {
84:               new OverlappingExecutionException("exception thrown after promise was fulfilled", e).printStackTrace();
85:             } else {
86:               executionFactory.join(new Action<ratpack.exec.Execution>() {
87:                 @Override
88:                 public void execute(ratpack.exec.Execution execution) throws Exception {
89:                   throw ExceptionUtils.toException(e);
90:                 }
91:               });
92:             }
93:           }
94:         }
95:       });
96:     } catch (Exception e) {
97:       throw new InternalRatpackError("failed to add promise resume action");
98:     }
99:   }
100: 
101: }
